<?php
declare(strict_types=1);
$u='CHAR(36) CHARACTER SET ascii COLLATE ascii_bin';$e=' ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci';
$sql=[
"INSERT INTO identity_permissions(code) VALUES ('support.mail_review')",
"INSERT INTO identity_role_permissions(role_id,permission) SELECT id,'support.mail_review' FROM identity_roles WHERE name IN ('Super Admin','Destek')",
"CREATE TABLE support_mail_tokens(id $u PRIMARY KEY,kind VARCHAR(16) NOT NULL,actor_id $u NOT NULL,customer_id $u NOT NULL,department_id $u NOT NULL,ticket_id $u NULL,file_id $u NULL,raw_sha CHAR(64) NULL,session_id $u NOT NULL,identity_version INT UNSIGNED NOT NULL,expiry BIGINT UNSIGNED NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(actor_id) REFERENCES identity_users(id),FOREIGN KEY(customer_id) REFERENCES identity_customers(id),FOREIGN KEY(session_id) REFERENCES identity_sessions(id),FOREIGN KEY(department_id) REFERENCES support_departments(id))$e",
"CREATE TABLE support_mail_claims(department_id $u NOT NULL,message_key CHAR(64) CHARACTER SET ascii NOT NULL,raw_sha CHAR(64) NOT NULL,PRIMARY KEY(department_id,message_key),FOREIGN KEY(department_id) REFERENCES support_departments(id))$e",
"CREATE TABLE support_mail_inbound(id $u PRIMARY KEY,department_id $u NOT NULL,message_key CHAR(64) CHARACTER SET ascii NOT NULL,raw_sha CHAR(64) CHARACTER SET ascii NOT NULL,raw_encrypted MEDIUMTEXT NULL,status VARCHAR(16) NOT NULL CHECK(status IN ('REVIEW','ATTACHED','BLOCKED','REJECTED')),reason VARCHAR(40) NOT NULL,customer_id $u NULL,ticket_id $u NULL,message_id $u NULL,version INT UNSIGNED NOT NULL DEFAULT 1,hold_content BOOLEAN NOT NULL DEFAULT FALSE,expires_at DATETIME(6) NOT NULL,purged_at DATETIME(6) NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE KEY uq_mail_variant(department_id,message_key,raw_sha),KEY ix_mail_review(department_id,status,id),FOREIGN KEY(department_id) REFERENCES support_departments(id),FOREIGN KEY(ticket_id,customer_id) REFERENCES support_tickets(id,customer_id),FOREIGN KEY(message_id) REFERENCES support_messages(id))$e",
"CREATE TABLE support_mail_sources(inbound_id $u PRIMARY KEY,ticket_id $u NOT NULL,customer_id $u NOT NULL,message_id $u NOT NULL UNIQUE,event_id $u NOT NULL UNIQUE,actor_id $u NOT NULL,proof_id $u NOT NULL,origin VARCHAR(24) NOT NULL CHECK(origin='TEST_ADAPTER'),created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(inbound_id) REFERENCES support_mail_inbound(id),FOREIGN KEY(ticket_id,customer_id) REFERENCES support_tickets(id,customer_id),FOREIGN KEY(message_id) REFERENCES support_messages(id),FOREIGN KEY(event_id) REFERENCES support_events(id),FOREIGN KEY(proof_id) REFERENCES support_mail_tokens(id),FOREIGN KEY(actor_id) REFERENCES identity_users(id))$e",
"CREATE TABLE support_mail_events(id $u PRIMARY KEY,subject_id $u NOT NULL,kind VARCHAR(40) NOT NULL,actor_id VARCHAR(64) CHARACTER SET ascii NOT NULL,details TEXT NOT NULL CHECK(JSON_VALID(details)),trace_id $u NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),KEY ix_mail_event(subject_id,created_at,id))$e",
"CREATE TABLE support_mail_outbound(id $u PRIMARY KEY,event_id $u NOT NULL UNIQUE,support_event_id $u NOT NULL UNIQUE,ticket_id $u NOT NULL,customer_id $u NOT NULL,message_id $u NOT NULL,recipient_id $u NULL,message_ref VARCHAR(100) CHARACTER SET ascii NOT NULL UNIQUE,status VARCHAR(32) NOT NULL CHECK(status IN ('PENDING','HELD','ACCEPTED_BY_TRANSPORT','RETRYABLE_FAILURE','PERMANENT_FAILURE')),version INT UNSIGNED NOT NULL DEFAULT 1,attempt_count INT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(ticket_id,customer_id) REFERENCES support_tickets(id,customer_id),FOREIGN KEY(support_event_id) REFERENCES support_events(id),FOREIGN KEY(message_id) REFERENCES support_messages(id),FOREIGN KEY(recipient_id) REFERENCES identity_users(id))$e",
"CREATE TABLE support_mail_attempts(id $u PRIMARY KEY,delivery_id $u NOT NULL,attempt_no INT UNSIGNED NOT NULL,outcome VARCHAR(32) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE KEY uq_mail_attempt(delivery_id,attempt_no),FOREIGN KEY(delivery_id) REFERENCES support_mail_outbound(id))$e",
"CREATE TABLE support_mail_dispatches(event_id $u PRIMARY KEY,delivery_id $u NOT NULL,attempt_no INT UNSIGNED NOT NULL,mode VARCHAR(32) NOT NULL,actor_id $u NOT NULL,UNIQUE KEY uq_mail_dispatch(delivery_id,attempt_no),FOREIGN KEY(delivery_id) REFERENCES support_mail_outbound(id),FOREIGN KEY(actor_id) REFERENCES identity_users(id))$e",
"CREATE TABLE support_mail_confirmations(id $u PRIMARY KEY,actor_id $u NOT NULL,session_id $u NOT NULL,identity_version INT UNSIGNED NOT NULL,action VARCHAR(24) NOT NULL,payload_hmac CHAR(64) NOT NULL,state_hmac CHAR(64) NOT NULL,expiry BIGINT UNSIGNED NOT NULL,used_at DATETIME(6) NULL,FOREIGN KEY(actor_id) REFERENCES identity_users(id),FOREIGN KEY(session_id) REFERENCES identity_sessions(id))$e",
"CREATE TABLE support_mail_transport(delivery_id $u PRIMARY KEY,recipient_id $u NOT NULL,content_hmac CHAR(64) NOT NULL,outcome VARCHAR(32) NOT NULL CHECK(outcome='ACCEPTED_BY_TRANSPORT'),created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(delivery_id) REFERENCES support_mail_outbound(id),FOREIGN KEY(recipient_id) REFERENCES identity_users(id))$e",
"CREATE TABLE support_mail_files(id $u PRIMARY KEY,ticket_id $u NOT NULL,customer_id $u NOT NULL,department_id $u NOT NULL,message_id $u NOT NULL,uploader_id $u NOT NULL,name_encrypted TEXT NOT NULL,sha256 CHAR(64) NOT NULL,byte_count INT UNSIGNED NOT NULL CHECK(byte_count BETWEEN 8 AND 16384),scan_status VARCHAR(24) NOT NULL CHECK(scan_status IN ('QUARANTINED','TEST_CLEAN')),physical_removed BOOLEAN NOT NULL DEFAULT FALSE,hold_content BOOLEAN NOT NULL DEFAULT FALSE,version INT UNSIGNED NOT NULL DEFAULT 1,expires_at DATETIME(6) NOT NULL,purged_at DATETIME(6) NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),KEY ix_mail_files(message_id,id),FOREIGN KEY(ticket_id,customer_id) REFERENCES support_tickets(id,customer_id),FOREIGN KEY(message_id) REFERENCES support_messages(id),FOREIGN KEY(department_id) REFERENCES support_departments(id),FOREIGN KEY(uploader_id) REFERENCES identity_users(id))$e",
"CREATE TABLE support_mail_retention(department_id $u PRIMARY KEY,enabled BOOLEAN NOT NULL DEFAULT FALSE,raw_days INT UNSIGNED NOT NULL CHECK(raw_days BETWEEN 1 AND 365),file_days INT UNSIGNED NOT NULL CHECK(file_days BETWEEN 1 AND 365),version INT UNSIGNED NOT NULL DEFAULT 1,FOREIGN KEY(department_id) REFERENCES support_departments(id))$e",
];
foreach(['support_mail_tokens','support_mail_sources','support_mail_events','support_mail_attempts','support_mail_transport','support_mail_claims','support_mail_dispatches'] as $t){foreach(['UPDATE','DELETE'] as $v){$s=strtolower($v);$sql[]="CREATE TRIGGER {$t}_no_{$s} BEFORE $v ON $t FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable mail evidence'";}}
$sql[]="CREATE TRIGGER mail_outbound_identity BEFORE UPDATE ON support_mail_outbound FOR EACH ROW BEGIN IF NOT(OLD.id<=>NEW.id) OR NOT(OLD.event_id<=>NEW.event_id) OR NOT(OLD.support_event_id<=>NEW.support_event_id) OR NOT(OLD.ticket_id<=>NEW.ticket_id) OR NOT(OLD.customer_id<=>NEW.customer_id) OR NOT(OLD.message_id<=>NEW.message_id) OR NOT(OLD.message_ref<=>NEW.message_ref) OR (OLD.recipient_id IS NOT NULL AND NOT(OLD.recipient_id<=>NEW.recipient_id)) OR NOT(OLD.created_at<=>NEW.created_at) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable outbound identity'; END IF; END";
$sql[]="CREATE TRIGGER mail_file_identity BEFORE UPDATE ON support_mail_files FOR EACH ROW BEGIN IF NOT(OLD.id<=>NEW.id) OR NOT(OLD.ticket_id<=>NEW.ticket_id) OR NOT(OLD.customer_id<=>NEW.customer_id) OR NOT(OLD.department_id<=>NEW.department_id) OR NOT(OLD.message_id<=>NEW.message_id) OR NOT(OLD.uploader_id<=>NEW.uploader_id) OR NOT(OLD.name_encrypted<=>NEW.name_encrypted) OR NOT(OLD.sha256<=>NEW.sha256) OR NOT(OLD.byte_count<=>NEW.byte_count) OR NOT(OLD.scan_status<=>NEW.scan_status) OR NOT(OLD.created_at<=>NEW.created_at) OR (OLD.purged_at IS NOT NULL AND NOT(OLD.purged_at<=>NEW.purged_at)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable attachment binding'; END IF; END";
$sql[]="CREATE TRIGGER mail_inbound_identity BEFORE UPDATE ON support_mail_inbound FOR EACH ROW BEGIN IF NOT(OLD.id<=>NEW.id) OR NOT(OLD.department_id<=>NEW.department_id) OR NOT(OLD.message_key<=>NEW.message_key) OR NOT(OLD.raw_sha<=>NEW.raw_sha) OR NOT(OLD.created_at<=>NEW.created_at) OR (OLD.raw_encrypted IS NOT NULL AND NEW.raw_encrypted IS NOT NULL AND NOT(OLD.raw_encrypted<=>NEW.raw_encrypted)) OR (OLD.purged_at IS NOT NULL AND (NEW.raw_encrypted IS NOT NULL OR NOT(OLD.purged_at<=>NEW.purged_at))) OR (OLD.status='ATTACHED' AND (NOT(OLD.customer_id<=>NEW.customer_id) OR NOT(OLD.ticket_id<=>NEW.ticket_id) OR NOT(OLD.message_id<=>NEW.message_id))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable inbound evidence'; END IF; END";
foreach(['support_mail_inbound','support_mail_outbound','support_mail_files'] as $t){$sql[]="CREATE TRIGGER {$t}_no_delete BEFORE DELETE ON $t FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Retain mail metadata'";}
return $sql;
